package com.styleshop.order.model;
import jakarta.persistence.*;import java.math.BigDecimal;
@Entity @Table(name="order_items") public class OrderItem {@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="order_id")private ShopOrder order;private Long productId;private String productName;private BigDecimal price;private String imageUrl;private int quantity;public Long getId(){return id;}public ShopOrder getOrder(){return order;}public void setOrder(ShopOrder v){order=v;}public Long getProductId(){return productId;}public void setProductId(Long v){productId=v;}public String getProductName(){return productName;}public void setProductName(String v){productName=v;}public BigDecimal getPrice(){return price;}public void setPrice(BigDecimal v){price=v;}public String getImageUrl(){return imageUrl;}public void setImageUrl(String v){imageUrl=v;}public int getQuantity(){return quantity;}public void setQuantity(int v){quantity=v;}}
